corrected_code:
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);
const { db } = require('../db');
const { mailer } = require('../mailer');

async function consumeDataExportStream() {
  while (true) {
    const streams = await redis.xreadgroup(
      'GROUP', 'export-workers', 'consumer-a',
      'BLOCK', 3000, 'COUNT', 5,
      'STREAMS', 'user:data-export:stream', '>'
    );
    if (!streams) continue;

    for (const [, messages] of streams) {
      for (const [id, fields] of messages) {
        const event = JSON.parse(fields[1]);
        const { targetUserId, requestedByUserId } = event;

        const targetUser = await db.query('SELECT email FROM users WHERE id = $1', [targetUserId]);
        if (targetUserId !== requestedByUserId || targetUser.rowCount === 0) {
          console.error(`Rejected unauthorized data export for ${targetUserId} requested by ${requestedByUserId}`);
          await redis.xack('user:data-export:stream', 'export-workers', id);
          continue;
        }

        const files = await db.query('SELECT file_url FROM user_vault_files WHERE user_id = $1', [targetUserId]);
        const archiveUrl = await generateArchive(targetUserId, files.rows);

        await mailer.sendMail({
          to: targetUser.rows[0].email,
          subject: 'Your Data Export Archive',
          text: `Download your data: ${archiveUrl}`
        });
        await redis.xack('user:data-export:stream', 'export-workers', id);
      }
    }
  }
}
